PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'ar', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('video','image','audio','font','other')), display_name TEXT NOT NULL, local_uri TEXT, mime_type TEXT, width INTEGER, height INTEGER, duration_ms INTEGER, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tracks (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('video','audio','text','graphics','effects')), name TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, muted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS clips (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, track_id TEXT NOT NULL REFERENCES tracks(id) ON DELETE CASCADE, asset_id TEXT REFERENCES assets(id) ON DELETE SET NULL, source_in_ms INTEGER NOT NULL DEFAULT 0, source_out_ms INTEGER NOT NULL, timeline_start_ms INTEGER NOT NULL DEFAULT 0, speed REAL NOT NULL DEFAULT 1.0, volume REAL NOT NULL DEFAULT 1.0, transform_json TEXT NOT NULL DEFAULT '{}', CHECK(source_in_ms >= 0 AND source_out_ms > source_in_ms AND timeline_start_ms >= 0));
CREATE TABLE IF NOT EXISTS captions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, track_id TEXT REFERENCES tracks(id) ON DELETE SET NULL, text TEXT NOT NULL, language TEXT NOT NULL DEFAULT 'ar', direction TEXT NOT NULL DEFAULT 'rtl', start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL, style_json TEXT NOT NULL DEFAULT '{}', CHECK(start_ms >= 0 AND end_ms > start_ms));
CREATE TABLE IF NOT EXISTS effects (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, clip_id TEXT REFERENCES clips(id) ON DELETE CASCADE, effect_type TEXT NOT NULL, parameters_json TEXT NOT NULL DEFAULT '{}', start_ms INTEGER, end_ms INTEGER);
CREATE TABLE IF NOT EXISTS transitions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, from_clip_id TEXT NOT NULL REFERENCES clips(id) ON DELETE CASCADE, to_clip_id TEXT NOT NULL REFERENCES clips(id) ON DELETE CASCADE, transition_type TEXT NOT NULL, duration_ms INTEGER NOT NULL CHECK(duration_ms >= 0), parameters_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS edit_plans (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'draft', brief TEXT NOT NULL, plan_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS render_jobs (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, plan_id TEXT REFERENCES edit_plans(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'queued', progress REAL NOT NULL DEFAULT 0, profile_json TEXT NOT NULL, output_uri TEXT, error TEXT, created_at TEXT NOT NULL, started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS ai_sessions (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, provider TEXT NOT NULL, model TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS provider_usage (id TEXT PRIMARY KEY, provider TEXT NOT NULL, model TEXT NOT NULL, task TEXT NOT NULL, input_units INTEGER, output_units INTEGER, estimated_cost REAL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_assets_project ON assets(project_id);
CREATE INDEX IF NOT EXISTS idx_clips_project_track ON clips(project_id, track_id);
CREATE INDEX IF NOT EXISTS idx_plans_project ON edit_plans(project_id, created_at);
CREATE INDEX IF NOT EXISTS idx_render_jobs_status ON render_jobs(status, created_at);
